var alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
function newId(time = Date.now(), random = crypto.getRandomValues(new Uint8Array(16))) {
  let stamp = "";
  for (let rest = time, i = 0;i < 10; i++, rest = Math.floor(rest / 32))
    stamp = alphabet[rest % 32] + stamp;
  let tail = "";
  for (let i = 0;i < 16; i++)
    tail += alphabet[random[i] % 32];
  return stamp + tail;
}

