import type { Json } from "../../src/store/canonical.ts";
import { canonical } from "../../src/store/canonical.ts";
import { newId, type Id } from "../../src/store/id.ts";
import type { Declaration, Given, Made, Space } from "../../src/interface/component.ts";
import type { Expression } from "../../src/engine/expression.ts";
import type { ExpressionBody, MountBody, Ref } from "./bodies.ts";
import { h } from "./jsx.ts";
import { overlay } from "./menu.ts";

// A mount: a component and what it gives it, drawn in full, offered what
// the mount offers. A mount that may be written is where what one looks at
// can change: a press anywhere inside it rises to it with where it leads,
// the innermost location it passed, a holon or a way of looking, maybe
// drawn by a component it names, or what the mount offers, and the mount
// takes it, a new version of itself. A way of looking the field does not
// yet hold is born in the home as the mount moves to it. On the secondary
// press it draws, where it was pressed, the search its holders or it
// itself offer, given the place pressed and the component that place is
// drawn by, so what can be done there is found as anything is. A mount
// that may not be written lets a press rise on.

export const declared = {
  title: "Mount",
  says: "A mount: what it gives, drawn by the component it calls, offered what it offers; where it may be written, a press inside it moves it to where the press leads, and its menu is the search, given the place pressed.",
  takes: ["mount"],
  kinds: ["full", "face"],
  reads: ["name", "instances", "holon", "gather"],
} satisfies Declaration;

export default async function draw(given: Given<MountBody>, space: Space) {
  const mount = given.holon!;
  const { title, component, argument } = mount.body;
  // What it offers, over what the entry offers, so a root made before the
  // entry offered something is offered it too.
  const entry = await space.read({ name: "entry" });
  const entered = entry && entry !== mount.id ? await space.holon<MountBody>(entry) : null;
  const offer = { ...(entered?.body.offer ?? {}), ...(mount.body.offer ?? {}) } as Record<string, Json>;
  const giving = argument.map(({ $ref }) => $ref);

  if (given.kind === "face")
    return (
      <div class="card">
        <strong>{title ?? "A mount"}</strong>
        <span class="meta">gives {giving.length === 1 ? "one holon" : `${giving.length} holons`}</span>
      </div>
    );

  const offering = { ...offer, kind: "full" as const };
  const drawn = space.open(giving.length === 1 ? giving[0]! : giving, {
    offer: offering,
    ...(component ? { component: component.$ref } : {}),
  });
  if (!given.may.write) return <div class="mount">{drawn}</div>;

  const element = (<div class="mount">{drawn}</div>) as HTMLElement;
  let closeMenu: (() => void) | undefined;

  // A component chosen to look with is for that one look: a plain move
  // calls again what the entry calls, the reader.
  const plainly = async () => (entered ?? mount).body.component?.$ref;

  const write = (body: Partial<MountBody>, made: Made[] = []) => {
    const { component: _, offer: __, ...rest } = mount.body;
    const next = { ...rest, ...body };
    return space.write(
      Object.fromEntries(Object.entries(next).filter(([, value]) => value !== undefined)) as never,
      made,
    );
  };
  const give = async (ids: Id[], by?: Id, made: Made[] = []) => {
    const calls = by ?? (await plainly());
    return write(
      {
        argument: ids.map(($ref) => ({ $ref })),
        ...(calls ? { component: { $ref: calls } } : {}),
        ...(Object.keys(offer).length ? { offer } : {}),
      },
      made,
    );
  };
  const same = (ids: Id[]) => JSON.stringify(ids) === JSON.stringify(giving);

  // A way of looking, as a place to go: the one the field holds that
  // gathers so, or else one born in the home as the mount moves to it.
  const look = async (gathers: Expression, title: string) => {
    const held = await heldWay(gathers, space);
    if (held) return same([held]) ? undefined : give([held]);
    const expression = await space.read({ name: "expression" });
    if (!expression) throw new Error("the field holds no type for ways of looking");
    const id = newId();
    return give([id], undefined, [{ id, instance: expression, body: { title, gathers } as never }]);
  };

  // What the mount offers, changed: each value said anew, or let go where
  // it is said as nothing.
  const offerAnew = (changed: Record<string, Json | null>) => {
    const next = { ...offer, ...changed };
    for (const [key, value] of Object.entries(next)) if (value === null) delete next[key];
    return write({
      argument,
      ...(component ? { component } : {}),
      ...(Object.keys(next).length ? { offer: next } : {}),
    });
  };

  // The innermost place a press passed, inside this mount.
  const pressedAt = (event: Event) => {
    const at = (event.target as Element).closest<HTMLElement>(
      "[data-location], [data-expression], [data-offer]",
    );
    return at && element.contains(at) ? at : null;
  };
  const go = (at: HTMLElement) => {
    if (at.dataset.offer) return offerAnew(JSON.parse(at.dataset.offer) as Record<string, Json | null>);
    if (at.dataset.expression)
      return look(JSON.parse(at.dataset.expression) as Expression, at.dataset.title ?? "A way of looking");
    const ids = JSON.parse(at.dataset.location!) as Id[];
    if (at.dataset.calls) return give(ids, at.dataset.calls);
    return same(ids) ? undefined : give(ids);
  };

  const press = (event: Event) => {
    const link = (event.target as Element).closest<HTMLAnchorElement>("a[href]");
    if (link && !link.dataset.location) return;
    const at = pressedAt(event);
    if (!at) return;
    event.preventDefault();
    event.stopPropagation();
    closeMenu?.();
    Promise.resolve(go(at)).catch((error: unknown) => console.error(error));
  };

  element.addEventListener("click", press);
  element.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    const target = event.target as HTMLElement;
    if (target.closest(".menu") || (!target.dataset.location && !target.dataset.expression)) return;
    press(event);
  });
  element.addEventListener("contextmenu", (event) => {
    if (event.shiftKey || (event.target as Element).closest(".menu")) return;
    event.preventDefault();
    event.stopPropagation();
    void menu(event, pressedAt(event)).catch((error: unknown) => console.error(error));
  });

  // The search, drawn where the press landed, given the place pressed and
  // the component it is drawn by; a way of looking not yet held is
  // searched from where the mount stands. The mount may move anywhere in
  // the field, so it reaches the whole of it.
  async function menu(event: MouseEvent, at: HTMLElement | null) {
    const search = ((offer.search as Ref | undefined) ?? (given.offered.search as Ref | undefined))?.$ref;
    if (!search) return;
    await space.read({ gather: { everything: true } });
    const place = at?.dataset.location ? (JSON.parse(at.dataset.location) as Id[]) : giving;
    const drawnBy = (at?.dataset.location ? at : (drawn as HTMLElement)).dataset.component;
    const opened = space.open(place.length === 1 ? place[0]! : place, {
      component: search,
      offer: offering,
      settings: { focused: true, ...(drawnBy ? { drawn: { $ref: drawnBy } } : {}) },
    });
    closeMenu?.();
    closeMenu = overlay(event.clientX, event.clientY, opened, element);
  }

  return element;
}

// The way of looking the field holds that gathers so, if it holds one,
// each told by its canonical form, as the store keeps it.
async function heldWay(gathers: Expression, space: Space): Promise<Id | undefined> {
  const expression = await space.read({ name: "expression" });
  if (!expression) return undefined;
  for (const id of await space.read({ instances: expression })) {
    const way = await space.holon<ExpressionBody>(id);
    if (way && canonical(way.body.gathers) === canonical(gathers)) return id;
  }
  return undefined;
}
